def merge_arrangement_resource_forward(apps, schema_editor):
    """把轮岗安排的 live_room / service_dept 两个旧 FK 归并到新的 resource FK。

    直播间与客服部门合并成一张资源表后，两个 FK 指向同一张表没有意义
    （一个安排只可能处于一个位置）→ 合并为单个 `resource` FK。

    取值口径：**live_room 优先，其次 service_dept**（旧模型里 live_room 是
    「具体位置（直播间）」、service_dept 是「客服部门」；两者同时有值时以
    live_room 为准 —— 它是表单上的「具体位置」主字段）。
    """
    RotationArrangement = apps.get_model('campus_rotation', 'RotationArrangement')
    for arr in RotationArrangement.objects.all().iterator():
        target = arr.live_room_id or arr.service_dept_id
        if target:
            arr.resource_id = target
            arr.save(update_fields=['resource_id'])


def merge_arrangement_resource_backward(apps, schema_editor):
    """回滚：把 resource FK 拆回 live_room / service_dept 两个旧 FK。

    口径：按 resource 指向的资源类型决定回到哪个字段
    （LIVE_ROOM → live_room，SERVICE_DEPT → service_dept，OTHER 两边都留空）。

    🔴 **先补齐旧表再写回 FK**：回滚到 0016 的过程中，「AddField(service_dept /
    live_room)」比「RunPython① backward（拆回行数据）」先跑 —— 若旧表此刻还是空表，
    已有的轮岗安排行（带着旧 FK 值）会撞外键约束。
    故这里先调 `_restore_legacy_tables()` 把旧表的行补齐（幂等）。
    """
    _restore_legacy_tables(apps)

    RotationArrangement = apps.get_model('campus_rotation', 'RotationArrangement')
    RotationResource = apps.get_model('campus_rotation', 'RotationResource')
    type_map = dict(RotationResource.objects.values_list('id', 'resource_type'))
    for arr in RotationArrangement.objects.all().iterator():
        if not arr.resource_id:
            continue
        rtype = type_map.get(arr.resource_id)
        if rtype == 'LIVE_ROOM':
            arr.live_room_id = arr.resource_id
        elif rtype == 'SERVICE_DEPT':
            arr.service_dept_id = arr.resource_id
        else:
            continue
        arr.save(update_fields=['live_room', 'service_dept'])


